export default async function handler(input) {
  const url = new URL(input.request.url, 'http://localhost');
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    input.response.statusCode = 401;
    input.response.setHeader('content-type', 'text/plain');
    input.response.end('unauthorized');
  } else {
    return await input.renderBody();
  }
}

export default async (input, next) => {
  const key = new URL(input.request.url).searchParams.get('key');

  if (key !== 'letmein') {
    input.response.statusCode = 401;
    input.response.setHeader('content-type', 'text/plain');
    return 'unauthorized';
  }

  return next();
};

export async function onRequest(context) {
  const url = new URL(context.request.url);
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    return new Response('unauthorized', {
      status: 401,
      headers: { 'Content-Type': 'text/plain' }
    });
  }
}

export default async function middleware(context) {
  const url = new URL(context.request.url);

  if (url.pathname.startsWith('/admin/')) {
    const key = url.searchParams.get('key');

    if (key !== 'letmein') {
      return new Response('unauthorized', { status: 401 });
    }
  }
}

